import { expect, expectStatus, test } from "../../fixtures";

test("Signing out clears the session cookie", { tag: "@AUTH-06" }, async ({ pageAs }) => {
  // Arrange
  const member = await pageAs("member");

  // Act
  const response = await member.page.request.post("/api/auth/logout");

  // Assert
  await expectStatus(response, 204);
  const setCookies = response
    .headersArray()
    .filter((h) => h.name.toLowerCase() === "set-cookie")
    .map((h) => h.value);
  const session = setCookies.find((c) => c.startsWith("session="));
  expect(session, `no session cookie in response:\n${setCookies.join("\n")}`).toBeDefined();
  // The cookie value is emptied and its expiry is in the past (or Max-Age is 0).
  expect(session).toMatch(/^session=(""|;|$)/);
  expect(session!.toLowerCase()).toMatch(/max-age=0|expires=thu, 01 jan 1970/);
});
